shell_commands:
python3 - <<'EOF'
p='src/orchestration/turnUsage.acceptance.test.ts'
s=open(p).read()
start=s.index("  it('counts the rounds")
end=s.rindex("});")
new='''  it('counts only the rounds that reported usage, and reports none when no round did', async () => {
    const partial = await reportedUsage([
      {inputTokens: 100, outputTokens: 10, totalTokens: 110},
      undefined,
      {inputTokens: 300, outputTokens: 30, totalTokens: 330},
    ]);
    const none = await reportedUsage([undefined, undefined, undefined]);

    expect({partial, none}).toEqual({partial: {inputTokens: 400, outputTokens: 40, totalTokens: 440}, none: undefined});
  });
'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
EOF
npx prettier --write src/orchestration/turnUsage.acceptance.test.ts && npm test -- src/orchestration/turnUsage.acceptance.test.ts 2>&1 | tail -60
